"""Writes the game's copy of the account rules' lists (godot/data/account_rules.json, read by
godot/scripts/account_rules.gd): run it after changing banned_words.txt, common_passwords.txt or rules.py's constants.
tests/test_accounts.py checks the copy is current."""

import json
from pathlib import Path

from plateau_accounts import rules

OUT = Path(__file__).resolve().parent.parent.parent / "godot/data/account_rules.json"

data = {
    "_about": "Generated by server/accounts/sync_client_rules.py from the accounts service's lists: don't edit.",
    "name_min": rules.NAME_MIN, "name_max": rules.NAME_MAX,
    "password_min": rules.PASSWORD_MIN, "password_max": rules.PASSWORD_MAX,
    "short_word": rules.SHORT_WORD,
    "reserved": rules.RESERVED,
    "banned": rules._list("banned_words.txt"),
    "common_passwords": sorted(rules.COMMON_PASSWORDS),
}
OUT.parent.mkdir(exist_ok=True)
OUT.write_text(json.dumps(data, ensure_ascii=False, indent=0) + "\n", encoding="utf-8")
print(f"Wrote {OUT}")
